<script setup lang="ts">import {computed,ref} from "vue";import {Upload,Check,Link2} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {formatMoney} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta("Bank Reconciliation","Import statements, review match suggestions and reconcile transactions.");const c=useCompanyStore(),state=useAsyncData(()=>operationsRepository.bankTransactions(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),selected=ref<string|null>(null);const rows=computed(()=>state.data.value??[]),unmatched=computed(()=>rows.value.filter(x=>x.status!=='matched'));async function match(id:string){await operationsRepository.updateTransaction(c.activeCompanyId,id,'matched');await state.refresh();showToast('Transaction matched','The reconciliation preview has been updated.')}function upload(){showToast('Statement parsed','4 preview transactions are ready for matching.','info')}</script><template><AppShell><PageHeader title="Bank Reconciliation" description="Statement matching workspace for the active company"><template #actions><ZButton variant="outline" @click="upload"><Upload class="size-4"/>Import CSV</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-3"><StatCard label="Statement items" :value="String(rows.length)"/><StatCard label="Suggested matches" :value="String(rows.filter(x=>x.status==='suggested').length)" tone="warning"/><StatCard label="Unmatched" :value="String(rows.filter(x=>x.status==='unmatched').length)" tone="danger"/></div><div class="grid gap-4 xl:grid-cols-2"><Panel title="Bank statement" description="Select an item to review its suggested book match"><div class="divide-y divide-line"><button v-for="x in rows" :key="x.id" class="flex w-full items-center justify-between gap-3 p-4 text-left hover:bg-surface-hover" :class="selected===x.id?'bg-surface-selected':''" @click="selected=x.id"><div><p class="text-sm font-medium text-content">{{x.description}}</p><p class="num mt-1 text-xs text-content-muted">{{x.date}} · {{x.reference}}</p></div><div class="text-right"><p class="num text-sm font-semibold" :class="x.direction==='in'?'text-success':'text-content'">{{x.direction==='in'?'+':'−'}}{{formatMoney(x.amount)}}</p><StatusBadge :status="x.status"/></div></button></div></Panel><Panel title="Suggested book match" description="Suggestions require confirmation before reconciliation"><div v-if="selected" class="p-5"><template v-if="rows.find(x=>x.id===selected)?.match_reference"><span class="grid size-10 place-items-center rounded-md bg-primary-subtle text-primary-subtle-fg"><Link2 class="size-5"/></span><p class="mt-4 label-caps">Suggested record</p><p class="mt-1 text-lg font-semibold text-content">{{rows.find(x=>x.id===selected)?.match_reference}}</p><p class="mt-2 text-sm text-content-secondary">{{rows.find(x=>x.id===selected)?.confidence}}% confidence based on amount, date and reference.</p><ZButton class="mt-5" @click="match(selected)"><Check class="size-4"/>Confirm match</ZButton></template><p v-else class="text-sm text-content-muted">No automatic match found. Choose a journal, invoice, bill or create an adjustment when the API is connected.</p></div><div v-else class="p-10 text-center text-sm text-content-muted">Select a statement item to compare it with company books.</div></Panel></div></AppShell></template>